/*
 * irq.h — dynamic interrupt vectors (M53c).
 *
 * Vectors 0x50..0xDF are handed out at run time to device interrupt sources
 * (MSI / MSI-X today, ring-3 driver claims from M57 on). Each has a generic
 * NASM stub (arch/x86/idt_asm.asm, generated by a macro) that calls
 * irq_dispatch(vec) between irq_enter/irq_exit; irq_dispatch runs the handler
 * bound to the vector and then sends the LAPIC EOI. Handlers never EOI.
 *
 * The fixed vectors stay outside this range and are never allocated:
 *   0x00-0x1F exceptions, 0x20-0x2F legacy IRQs (timer 0x20, keyboard 0x21,
 *   PS/2 mouse 0x2C), 0x40-0x42 reserved (the pre-M53c fixed xHCI/NVMe/NET
 *   vectors; no longer installed), 0x80 syscall, 0xF0-0xF2 IPIs, 0xFF LAPIC
 *   spurious.
 *
 * One vector namespace for the whole system: a vector is bound to one target
 * CPU (the CPU its message is addressed to), and the same number is never
 * given to two sources on different CPUs. 144 vectors are plenty for now, and
 * retargeting a source to another CPU never changes its vector, so an
 * interrupt already in flight to the old CPU still finds the right handler.
 *
 * Lifetime: irq_vec_free() unbinds the vector and then waits until no CPU is
 * still running its handler, so after it returns the handler and its ctx are
 * no longer used. The caller must have silenced the source (MSI-X entry
 * masked / MSI disabled) first. An interrupt latched in a LAPIC before that
 * may still arrive later; it is counted as spurious (or, if the vector was
 * already reused, reaches the new owner once: handlers must tolerate a stray
 * call). Never call irq_vec_free() from the vector's own handler.
 *
 * Locking: g_irqvec_lock (LK_S66_IRQVEC, leaf, IRQ-safe) around alloc/free
 * only; irq_dispatch is lock-free.
 *
 * SPDX-License-Identifier: MIT
 */
#ifndef IRQ_H
#define IRQ_H
#include <stdint.h>

#define IRQ_VEC_FIRST   0x50
#define IRQ_VEC_LAST    0xDF
#define IRQ_VEC_COUNT   (IRQ_VEC_LAST - IRQ_VEC_FIRST + 1)   /* 144 */

/* Target-CPU argument: let the allocator choose (today: the BSP). */
#define IRQ_CPU_ANY     0xFFFFFFFFu

/* A handler runs in hardware-interrupt context, IF=0, on the CPU the message
 * was delivered to: no sleeping, no klocks, IRQ-safe spinlocks only. */
typedef void (*irq_handler_t)(uint8_t vec, void* ctx);

/* Bind a free vector to `handler(vec, ctx)`, targeted at CPU index `cpu`
 * (or IRQ_CPU_ANY). `name` (static string) shows in /proc/interrupts.
 * Returns the vector, or -1 (no free vector / bad CPU / NULL handler). */
int irq_vec_alloc(uint32_t cpu, irq_handler_t handler, void* ctx, const char* name);

/* A block of `count` consecutive vectors (a power of two, <= 32) whose base is
 * aligned to `count` (what MSI multi-message needs: the device ORs the message
 * number into the low data bits). Every vector gets the same handler + ctx;
 * the handler tells them apart by `vec - base`. Returns the base or -1. */
int irq_vec_alloc_block(uint32_t cpu, uint32_t count, irq_handler_t handler,
                        void* ctx, const char* name);

/* Unbind and wait for running handlers (see above). Ignores a vector outside
 * the dynamic range or not allocated. */
void irq_vec_free(int vec);
void irq_vec_free_block(int base, uint32_t count);

/* The CPU index a vector is targeted at (-1 if not allocated), and a way to
 * record a new target after the caller reprogrammed the source. [M56] With
 * interrupt remapping on, irq_vec_set_cpu also retargets the vector's
 * remapping entry (the source itself needs no rewrite), and irq_vec_free
 * clears it. */
int irq_vec_cpu(int vec);
int irq_vec_set_cpu(int vec, uint32_t cpu);

/* Resolve IRQ_CPU_ANY / validate a CPU index: the index to target, or -1. */
int irq_pick_cpu(uint32_t cpu);

/* Called from the generic stubs only. */
void irq_dispatch(uint64_t vec);

/* Counters for /proc/interrupts: one line per allocated vector plus the
 * spurious total. `emit` is called once per line (NUL-terminated, with \n). */
void irq_vec_generate(void (*emit)(void* ctx, const char* line), void* ctx);
uint64_t irq_spurious_count(void);
uint32_t irq_vec_free_count(void);

/* Boot self-test (needs the LAPIC): self-IPIs to an allocated vector reach
 * its handler with its ctx, an AP-targeted vector runs on that AP, a freed
 * vector is counted as spurious and never calls the old handler, blocks are
 * aligned, the allocator refuses when full. Logs [IRQ] ... PASS/FAIL. */
void irq_vec_selftest(void);

#endif /* IRQ_H */
